agent_sql:
SELECT 
  (SELECT COUNT(*) FROM (
      SELECT seller_id FROM delivered_orders WHERE n_sellers=1 GROUP BY seller_id HAVING COUNT(*)>=100
  )) AS seller_count,
  (SELECT seller_id FROM delivered_orders WHERE n_sellers=1 GROUP BY seller_id HAVING COUNT(*)>=100 ORDER BY AVG(is_late) DESC LIMIT 1) AS top_seller_id,
  (SELECT ROUND(100.0*AVG(is_late),2) FROM delivered_orders WHERE n_sellers=1 GROUP BY seller_id HAVING COUNT(*)>=100 ORDER BY AVG(is_late) DESC LIMIT 1) AS top_late_rate;

SELECT ROUND(100.0 * AVG(is_late), 2) AS late_rate
FROM delivered_orders
WHERE n_sellers = 1 AND seller_state = 'SP' AND same_state = 0;
